'use strict';
const TODAY=productionToday;
const KEY='mimine-flow-preferences';
const $=(s,r=document)=>r.querySelector(s);
const $$=(s,r=document)=>[...r.querySelectorAll(s)];
const fmt=n=>Math.round(Number(n)||0).toLocaleString('ko-KR');
const won=n=>fmt(n)+'원';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=s=>Math.max(0,Math.round(Number(String(s??'').replace(/[^0-9.-]/g,''))||0));
const moneyMarkup=n=>`${fmt(n)}<span>원</span>`;
function todaySalesAmount(markup,label='매출'){return`<button type="button" class="revenue-shortcut" data-action="today-sale" aria-label="${esc(label)} · 오늘 매출 입력·수정" title="오늘 매출 입력·수정">${markup}${icon('edit','revenue-edit-cue')}</button>`;}
const uid=p=>p+'-'+(globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2));
const day=d=>new Date(d+'T12:00:00Z');
const addDays=(d,n)=>{const x=day(d);x.setUTCDate(x.getUTCDate()+n);return x.toISOString().slice(0,10)};
const md=d=>`${Number(d.slice(5,7))}.${Number(d.slice(8))}`;
const weekday=d=>['일','월','화','수','목','금','토'][day(d).getUTCDay()];
const dateText=d=>`${Number(d.slice(5,7))}월 ${Number(d.slice(8))}일 ${weekday(d)}요일`;
const daysBetween=(a,b)=>Math.round((day(b)-day(a))/86400000);
const sum=(arr,f=x=>x.amount)=>arr.reduce((a,x)=>a+(Number(f(x))||0),0);
const iconPaths={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z"/>',ledger:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 7h8M8 12h3M8 16h3M15 12h1M15 16h1"/>',bank:'<path d="m3 9 9-6 9 6H3ZM4 21h16M6 9v8M12 9v8M18 9v8M4 18h16"/>',box:'<path d="m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 4 9-4M12 11v11M7.5 5 17 9"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',left:'<path d="m14 6-6 6 6 6"/>',right:'<path d="m10 6 6 6-6 6"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',chart:'<path d="M4 20h17M7 16V9M12 16V4M17 16v-5"/>',settings:'<path d="M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Z"/><path d="m10 3-.5 2-2 .8-1.8-.7-2 3.4 1.5 1.4L5 12l.2 2.1-1.5 1.4 2 3.4 1.8-.7 2 .8.5 2h4l.5-2 2-.8 1.8.7 2-3.4-1.5-1.4.2-2.1-.2-2.1 1.5-1.4-2-3.4-1.8.7-2-.8-.5-2h-4Z"/>',sales:'<path d="M3 17h18M5 17V7h14v10M9 7V4h6v3M9 12h6"/>',expense:'<rect x="3" y="6" width="18" height="14" rx="3"/><path d="M3 10h18M15 15h2M6 6V4h11"/>',arrowUp:'<path d="m6 14 6-6 6 6M12 8v12"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',check:'<path d="m5 12 4 4L19 6"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M7 14h2M13 14h2"/>',spark:'<path d="m12 3 2.6 6.4L21 12l-6.4 2.6L12 21l-2.6-6.4L3 12l6.4-2.6L12 3Z"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',link:'<path d="m10 13 4-4M8 15l-2 2a3.5 3.5 0 0 1-5-5l4-4a3.5 3.5 0 0 1 5 0m4 1 2-2a3.5 3.5 0 0 1 5 5l-4 4a3.5 3.5 0 0 1-5 0"/>',ramen:'<path d="M3 12h18c0 6-4 8-9 8s-9-2-9-8ZM6 21h12M8 9c-3-3 3-3 0-6M12 9c-3-3 3-3 0-6M16 9c-3-3 3-3 0-6"/>',drink:'<path d="M8 3h8M9 3v4l-3 4v9a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1v-9l-3-4V3M6 13h12M6 17h12"/>',alert:'<path d="m10 4-8 14a2 2 0 0 0 2 3h16a2 2 0 0 0 2-3L14 4a2 2 0 0 0-4 0ZM12 9v5M12 17h.01"/>',edit:'<path d="m14 5 5 5M4 20l5-1L21 7a2 2 0 0 0-4-4L5 15l-1 5Z"/>',trash:'<path d="M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5"/><path d="M6 7a7 7 0 0 1 12-1l2 4M4 14l2 4a7 7 0 0 0 12-1"/>',tag:'<path d="M20 13 11 22 2 13V3h10l8 8v2Z"/><circle cx="7" cy="8" r="1"/>'};
const icon=(n,cl='')=>`<svg viewBox="0 0 24 24" aria-hidden="true" ${cl?`class="${cl}"`:''}>${iconPaths[n]||iconPaths.info}</svg>`;
function seed(){throw new Error('운영 화면은 예시 데이터를 생성하지 않습니다.');}
let storageAvailable=true,db=structuredClone(productionSnapshot);
const view={page:'today',date:TODAY,range:'month',customStart:TODAY.slice(0,7)+'-01',customEnd:TODAY,ledgerType:'all',bankTab:'transactions',bankFilter:'all',bankBusiness:'all',productFilter:'all',query:'',productQuery:'',reportRange:'month'};
let previousFocus=null,modalName='',modalContext={},toastTimer,undoFn=null;
function persist(){preferenceSave();}
function notifyMutation(message){persist();render();toast(message);}
function toast(message,undo){clearTimeout(toastTimer);undoFn=undo||null;$('#toast').innerHTML=esc(message)+(undo?'<button data-action="undo">되돌리기</button>':'');$('#toast').classList.add('show');toastTimer=setTimeout(()=>{$('#toast').classList.remove('show');undoFn=null;},undo?6500:3200);}
const saleOn=d=>db.sales.find(s=>s.date===d);
const stock=p=>sum(p.batches,b=>b.qty);
const expiry=p=>p.batches.filter(b=>b.qty>0&&b.expiry).map(b=>b.expiry).sort()[0]||'';
const expiring=p=>!!expiry(p)&&daysBetween(TODAY,expiry(p))<=7&&stock(p)>0;
const linked=s=>sum(db.links.filter(l=>l.saleId===s.id));
const expected=s=>Math.max(0,(s.card||0)-(s.fee||0));
const remaining=s=>Math.max(0,expected(s)-linked(s));
const available=e=>e.excluded?0:Math.max(0,e.amount-sum(db.links.filter(l=>l.eventId===e.id)));
function saleStatus(s){if(!s.card)return '현금 매출';if(!s.due)return '예정일 미등록';if(!remaining(s))return '입금 완료';if(linked(s))return '일부 입금';return s.due<=TODAY?'확인 필요':'입금 예정';}
function rangeBounds(r=view.range){if(r==='today')return[view.date,view.date];if(r==='week')return[addDays(view.date,-6),view.date];if(r==='custom')return[view.customStart,view.customEnd];return[view.date.slice(0,7)+'-01',view.date.slice(0,7)===TODAY.slice(0,7)?TODAY:view.date.slice(0,7)+'-31'];}
const inRange=(x,b)=>x.date>=b[0]&&x.date<=b[1];
const rangeLabel=()=>{const[a,b]=rangeBounds();return `${a.replaceAll('-','.')} – ${b.replaceAll('-','.')}`;};
function activeSettlements(){const month=view.date.slice(0,7);return db.sales.filter(s=>s.card>0&&(s.date.startsWith(month)||s.due?.startsWith(month))).sort((a,b)=>b.date.localeCompare(a.date));}
function allRecords(bounds){return[...db.sales.filter(s=>inRange(s,bounds)).map(s=>({...s,type:'sale'})),...db.expenses.filter(e=>inRange(e,bounds)).map(e=>({...e,type:'expense'}))].sort((a,b)=>b.date.localeCompare(a.date)||(a.type==='expense'?-1:1));}
function navHTML(){const pages=[['today','홈','home'],['ledger','장부','ledger'],['bank','입금','bank'],['products','상품','box']];const pending=activeSettlements().filter(s=>remaining(s)&&s.due<=TODAY).length;
 $('#desktop-nav').innerHTML=pages.map(([id,label,i])=>`<button class="nav-item ${view.page===id?'active':''}" data-action="navigate" data-page="${id}" ${view.page===id?'aria-current="page"':''}>${icon(i)}${label}${id==='bank'&&pending?`<span class="nav-count">${pending}</span>`:''}</button>`).join('');
 $('#mobile-nav').innerHTML=pages.map(([id,label,i],idx)=>`${idx===2?`<button class="nav-analysis ${view.page==='reports'?'active':''}" data-action="navigate" data-page="reports" ${view.page==='reports'?'aria-current="page"':''}>${icon('chart')}<span>비교·예측</span></button>`:''}<button class="${view.page===id?'active':''}" data-action="navigate" data-page="${id}" ${view.page===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='bank'&&pending?'<i class="nav-dot"></i>':''}</button>`).join('');
 $('#reports-nav').innerHTML=icon('chart')+'비교·예측';$('#reports-nav').classList.toggle('active',view.page==='reports');$('#settings-nav').innerHTML=icon('settings')+'설정·연결';$('#top-report').innerHTML=icon('chart');$('#top-settings').innerHTML=icon('settings');$('#breadcrumb').innerHTML='매장 관리 <span>/</span> '+({today:'매출·비용',ledger:'장부',bank:'입금 확인',products:'상품·재고',reports:'비교·예측'}[view.page]||'오늘');
}
function dateSwitch(){return`<div class="date-switch" aria-label="조회일 변경"><button class="icon-button" data-action="date-prev" aria-label="이전 날짜">${icon('left')}</button><button class="date-label" data-action="date-picker" aria-label="조회 날짜 선택">${md(view.date)} ${weekday(view.date)}요일</button><button class="icon-button" data-action="date-next" ${view.date>=TODAY?'disabled':''} aria-label="다음 날짜">${icon('right')}</button></div>`;}
function heading(eng,title,sub,action=''){return`<div class="page-heading"><div><p class="eyebrow">${eng}</p><h1>${title}</h1>${sub?`<p class="subtext">${sub}</p>`:''}</div>${action}</div>`;}
function recordRow(r){const sale=r.type==='sale';return`<button class="record-row" data-action="edit-record" data-id="${esc(r.id)}" data-type="${sale?'sale':'expense'}" aria-label="${esc((sale?'일매출':r.vendor||r.category)+' '+won(r.amount)+' 수정')}"><span class="record-icon ${sale?'':'expense'}">${icon(sale?'sales':'expense')}</span><span class="record-content"><strong>${sale?'일매출 마감':esc(r.vendor||r.category)}</strong><small>${sale?`카드 ${won(r.card)} · 현금 ${won(r.cash)}`:esc(r.category)+(r.note?' · '+esc(r.note):'')}</small></span><span class="record-amount ${sale?'positive':''}">${sale?'+':'−'}${won(r.amount)}<small>${sale?r.source||'수동 입력':'지출'}</small></span></button>`;}
function chart(dates,cls=''){const values=dates.map(d=>saleOn(d)?.amount||0),max=Math.max(...values,1);return`<div class="chart-columns ${cls}" aria-label="일별 매출 그래프">${dates.map((d,i)=>`<button class="chart-col ${d===view.date?'current':''}" data-action="chart-date" data-date="${d}" aria-label="${dateText(d)} 매출 ${won(values[i])}"><div class="chart-track"><div class="chart-bar" style="height:${Math.max(3,values[i]/max*100)}%"></div></div><span>${md(d)}</span></button>`).join('')}</div>`;}
function renderToday(){const s=saleOn(view.date),y=saleOn(addDays(view.date,-1)),todaySales=s?.amount||0,todayExpense=sum(db.expenses.filter(e=>e.date===view.date));const month=view.date.slice(0,7),ms=sum(db.sales.filter(s=>s.date.startsWith(month))),me=sum(db.expenses.filter(e=>e.date.startsWith(month)));const pending=activeSettlements().filter(s=>remaining(s)&&s.due&&s.due<=TODAY).sort((a,b)=>a.date.localeCompare(b.date));const lows=db.products.filter(p=>stock(p)<=p.min);const exp=db.products.filter(expiring);const tasks=(pending.length>0?1:0)+(lows.length>0?1:0)+(exp.length>0?1:0);const week=Array.from({length:7},(_,i)=>addDays(view.date,i-6));const records=allRecords([view.date,view.date]);const ratio=db.goal?Math.round(ms/db.goal*100):0;const gain=y?.amount?Math.round((todaySales-y.amount)/y.amount*100):null;
 return heading('DAILY OVERVIEW','오늘의 운영',dateText(view.date),dateSwitch())+`<div class="home-grid"><div class="home-main"><section class="sales-hero" aria-label="오늘 매출 요약"><div class="hero-label">${view.date===TODAY?'오늘':'선택일'} 매출</div><div class="hero-value">${moneyMarkup(todaySales)}</div><p class="hero-comparison">${icon(gain!==null&&gain>=0?'arrowUp':'chart')}${s?(gain===null?'등록된 일매출 기준':`전날보다 ${gain>=0?'+':''}${gain}% · ${won(y.amount)}`):'아직 매출을 입력하지 않았어요'}</p><span class="hero-pill">MIMINE DAILY</span><img class="hero-watermark" src="__LOGO__" alt=""><div class="hero-sub"><div><small>${view.date===TODAY?'오늘':'선택일'} 지출</small><strong>${moneyMarkup(todayExpense)}</strong></div><div><small>매출 − 지출</small><strong>${moneyMarkup(todaySales-todayExpense)}</strong></div></div></section><div class="quick-actions"><button class="quick-action" data-action="entry" data-type="sale"><span class="action-icon">${icon('plus')}</span>매출 입력</button><button class="quick-action" data-action="entry" data-type="expense"><span class="action-icon">${icon('minus')}</span>지출 입력</button></div><section class="card weekly-card"><div class="card-header"><h2>최근 7일 매출</h2><span class="chart-legend"><i></i> 일매출</span></div>${chart(week)}<div class="chart-note"><span>하루 평균</span><strong>${won(Math.round(sum(week,d=>saleOn(d)?.amount||0)/7))}</strong><button class="text-button" data-action="navigate" data-page="reports">분석 보기${icon('right')}</button></div></section><section class="card recent-card"><div class="card-header"><h2>오늘 기록 <span class="count-badge">${records.length}</span></h2><button class="text-button" data-action="go-ledger-today">전체${icon('right')}</button></div><div class="clean-list">${records.length?records.map(recordRow).join(''):'<div class="empty"><p>아직 기록이 없어요.</p><button class="secondary compact" data-action="entry">첫 기록 등록</button></div>'}</div></section></div><div class="home-side"><section class="card attention-card"><div class="card-header"><h2>지금 확인 <span class="count-badge">${tasks}</span></h2><small>처리할 일</small></div>${pending.length?`<button class="task-row" data-action="go-pending"><span class="task-icon red">${icon('bank')}</span><span class="task-body"><strong>카드정산 입금 확인</strong><small>${md(pending[0].date)} 매출 · ${pending[0].due<TODAY?'예정일이 지났어요':'오늘 입금 예정이에요'}</small></span><span class="task-meta">${pending.length}건</span>${icon('right')}</button>`:''}${lows.length?`<button class="task-row" data-action="go-products" data-filter="low"><span class="task-icon">${icon('box')}</span><span class="task-body"><strong>재고가 부족한 상품</strong><small>${esc(lows.slice(0,2).map(p=>p.name).join(' · '))}</small></span><span class="task-meta">${lows.length}개</span>${icon('right')}</button>`:''}${exp.length?`<button class="task-row" data-action="go-products" data-filter="expiry"><span class="task-icon green">${icon('clock')}</span><span class="task-body"><strong>7일 안에 유통기한</strong><small>먼저 판매할 상품을 확인하세요</small></span><span class="task-meta">${exp.length}개</span>${icon('right')}</button>`:''}${!tasks?`<div class="empty">${icon('check')}<h3>확인할 일을 모두 처리했어요</h3><p>오늘도 수고하셨습니다.</p></div>`:''}</section><section class="card month-card"><div class="card-header"><h2>${Number(month.slice(5))}월 운영 현황</h2><button class="text-button" data-action="navigate" data-page="reports" aria-label="월간 분석 보기">${icon('right')}<span class="hidden">분석 보기</span></button></div><div class="mini-metrics"><div class="mini-metric"><span>누적 매출</span><strong>${won(ms)}</strong></div><div class="mini-metric"><span>누적 지출</span><strong>${won(me)}</strong></div><div class="mini-metric total"><span>매출 − 지출</span><strong class="${changeTone(ms-me)}">${won(ms-me)}</strong></div></div><p class="section-note">${month} · 입력된 금액 기준</p></section><section class="card goal-panel"><div class="card-header"><h2>이번 달 매출 목표</h2><button class="text-button" data-action="goal" aria-label="매출 목표 수정">${icon('edit')}<span class="hidden">목표 수정</span></button></div><div class="goal-value">${ratio}<span>% 달성</span></div><div class="progress-track" role="progressbar" aria-label="매출 목표 달성률" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,ratio)}"><div class="progress-bar" style="width:${Math.min(100,ratio)}%"></div></div><div class="goal-label"><span>${won(ms)}</span><span>목표 ${won(db.goal)}</span></div><p>${db.goal>ms?'목표까지 '+won(db.goal-ms)+' 남았어요.':'이번 달 목표를 달성했어요.'}</p></section></div></div>`;
}
function rangeControls(){return`<div class="range-buttons" aria-label="조회 기간">${[['today','오늘'],['week','최근 7일'],['month','이번 달'],['custom','기간 선택']].map(([id,l])=>`<button class="${view.range===id?'active':''}" data-action="range" data-range="${id}">${l}${id==='custom'?' '+icon('calendar'):''}</button>`).join('')}</div>`;}
function emptyHTML(title,desc,action=''){return`<div class="empty">${icon('ledger')}<h3>${esc(title)}</h3><p>${esc(desc)}</p>${action}</div>`;}
function renderLedger(){const bounds=rangeBounds(),ss=db.sales.filter(s=>inRange(s,bounds)),ee=db.expenses.filter(e=>inRange(e,bounds)),totalS=sum(ss),totalE=sum(ee);let records=allRecords(bounds).filter(r=>view.ledgerType==='all'||r.type===view.ledgerType);const q=view.query.toLowerCase();if(q)records=records.filter(r=>[r.date,r.vendor,r.category,r.note,r.type==='sale'?'매출 마감':'지출',String(r.amount)].join(' ').toLowerCase().includes(q));const grouped={};records.forEach(r=>(grouped[r.date]??=[]).push(r));
 return heading('CASHBOOK','매출·지출 장부','날짜별 기록을 한곳에서 확인하고 수정하세요.',`<button class="secondary compact" data-action="export">${icon('download')}내보내기</button>`)+`<div class="page-toolbar"><div class="segmented" aria-label="장부 유형">${[['all','전체'],['sale','매출'],['expense','지출']].map(([id,l])=>`<button class="${view.ledgerType===id?'active':''}" data-action="ledger-type" data-value="${id}">${l}</button>`).join('')}</div>${rangeControls()}</div><p class="date-range-caption">${rangeLabel()}</p><div class="summary-grid"><button type="button" class="summary-card sales-summary-shortcut" data-action="today-sale" aria-label="기간 매출 · 오늘 매출 입력·수정"><small>매출 ${icon('plus')}</small><strong class="positive">${moneyMarkup(totalS)}</strong><em>${ss.length}일 입력 · 눌러서 오늘 매출 입력</em></button><div class="summary-card"><small>지출</small><strong>${moneyMarkup(totalE)}</strong><em>${ee.length}건 등록</em></div><div class="summary-card"><small>매출 − 지출</small><strong class="${changeTone(totalS-totalE)}">${moneyMarkup(totalS-totalE)}</strong><em>선택 기간 기준</em></div></div><div class="search-line"><label class="search-box">${icon('search')}<input data-search="ledger" aria-label="장부 검색" placeholder="내역·금액·메모 검색" value="${esc(view.query)}"></label><small>${records.length}건의 기록</small></div><section class="list-card ledger-list"><div class="list-header"><span>거래 내역 · 누르면 수정</span><span>금액</span></div>${Object.entries(grouped).map(([d,rs])=>`<div class="list-group"><div class="group-date">${dateText(d)}<span>${rs.length}건</span></div>${rs.map(recordRow).join('')}</div>`).join('')||emptyHTML('조건에 맞는 기록이 없어요','기간이나 검색어를 바꾸거나 새 기록을 등록하세요.','<button class="primary compact" data-action="entry">기록 등록</button>')}<div class="list-bottom">매출은 하루 1건으로 관리해 중복 입력을 줄입니다.</div></section>`;
}
function settlementCard(s){const got=linked(s),rem=remaining(s),stat=saleStatus(s),tag=stat==='입금 완료'?'green':stat==='확인 필요'?'red':'amber';return`<section class="settlement-card"><div class="settlement-top"><strong>${dateText(s.date)} 매출</strong><span class="pill ${tag}">${stat}</span></div><div class="settlement-values"><div><small>카드 입금 예정액</small><strong>${moneyMarkup(expected(s))}</strong></div><div><small>연결된 입금</small><strong class="${rem?'':'positive'}">${moneyMarkup(got)}</strong></div></div><div class="bank-breakdown"><span>${todaySalesAmount('카드매출 '+won(s.card),'카드매출')}</span><span>수수료 −${won(s.fee)}</span></div><div class="settlement-bottom"><span>${s.due?'입금 예정 '+md(s.due):'예정일 미등록'}${rem&&s.due<TODAY?' · 기한 경과':''}</span>${rem?`<button class="primary compact" data-action="match" data-id="${s.id}">입금 확인${icon('right')}</button>`:`<button class="text-button" data-action="match" data-id="${s.id}">${icon('check')}연결 보기</button>`}</div></section>`;}
function renderBank(){const settlements=activeSettlements(),due=settlements.filter(s=>s.due<=TODAY),pending=settlements.filter(s=>remaining(s)),totalExpected=sum(settlements,expected),got=sum(settlements,linked),need=sum(due,remaining);const filtered=settlements.filter(s=>view.bankFilter==='all'||(view.bankFilter==='pending'?remaining(s)>0:remaining(s)===0));const events=db.events.filter(e=>e.date.startsWith(view.date.slice(0,7))).filter(e=>view.bankBusiness==='all'||e.business===view.bankBusiness).sort((a,b)=>b.date.localeCompare(a.date)||b.time.localeCompare(a.time));
 return heading('SETTLEMENT','입금 확인','카드매출과 실제 통장 입금을 나란히 비교하세요.',`<button class="secondary compact" data-action="bank-settings">${icon('settings')}연결 설정</button>`)+`<div class="page-toolbar"><div class="segmented"><button class="${view.bankTab==='compare'?'active':''}" data-action="bank-tab" data-value="compare">카드정산 확인</button><button class="${view.bankTab==='transactions'?'active':''}" data-action="bank-tab" data-value="transactions">통장내역</button></div><span class="pill">${view.date.slice(0,7).replace('-','.')} 기준</span></div>${view.bankTab==='compare'?`<div class="summary-grid"><div class="summary-card overview"><small>카드 입금 예정</small><strong>${moneyMarkup(totalExpected)}</strong><em>수수료 차감 후</em></div><div class="summary-card overview"><small>입금 연결 완료</small><strong class="positive">${moneyMarkup(got)}</strong><em>${settlements.filter(s=>!remaining(s)).length}건 정산 완료</em></div><div class="summary-card overview"><small>지금 확인할 금액</small><strong class="negative">${moneyMarkup(need)}</strong><em>예정일 도래 기준</em></div></div><div class="bank-layout"><div class="stack"><div class="soft-notice">${icon('info')}<span>매출일과 입금일이 달라도 연결할 수 있어요. 입금은 장부 매출에 중복 합산하지 않습니다.</span></div><div class="page-toolbar" style="margin:0"><div class="product-filters">${[['all','전체'],['pending','미완료'],['done','완료']].map(([id,l])=>`<button class="chip ${view.bankFilter===id?'active':''}" data-action="bank-filter" data-value="${id}">${l}</button>`).join('')}</div><button class="text-button accent" data-action="auto-match">${icon('spark')}자동 연결 체험</button></div>${filtered.map(settlementCard).join('')||`<div class="card">${emptyHTML('확인할 정산이 없어요','다른 상태를 선택해 보세요.')}</div>`}</div><div class="stack bank-side"><section class="card"><div class="card-header"><h2>입금 확인 순서</h2>${icon('link')}</div><div class="bank-timeline"><div class="timeline-step"><strong>1. 일매출 입력</strong><p>매출을 카드·현금으로 구분합니다.</p></div><div class="timeline-step"><strong>2. 수수료·예정일 확인</strong><p>입금 예정액을 실제 정산표와 맞춥니다.</p></div><div class="timeline-step"><strong>3. 통장 입금 연결</strong><p>일치하는 입금을 선택하면 완료됩니다.</p></div></div></section><section class="card"><h3>체험용 통장내역</h3><p class="section-note">이 목업에서는 예시 입금을 추가하고 분류·연결 과정을 직접 체험할 수 있습니다.</p><button class="secondary compact full spacer" data-action="sample-bank">${icon('plus')}예시 입금 추가</button></section></div></div>`:`<div class="soft-notice neutral" style="margin-bottom:18px">${icon('info')}<span>예시 우리은행 통장 · 미미네와 하루온종일의 입금을 사업별로 구분합니다.</span></div><div class="page-toolbar"><div class="product-filters">${[['all','전체'],['mimine','미미네'],['adw','하루온종일'],['unclassified','미분류']].map(([id,l])=>`<button class="chip ${view.bankBusiness===id?'active':''}" data-action="business-filter" data-value="${id}">${l}</button>`).join('')}</div><button class="text-button accent" data-action="sample-bank">${icon('plus')}예시 입금 추가</button></div><div class="list-card">${events.map(e=>`<div class="bank-entry"><div class="bank-entry-top"><strong>${esc(e.payer)}</strong><span class="money">+${won(e.amount)}</span></div><div class="bank-entry-meta"><span>${e.date.slice(5).replace('-','.')} ${e.time} · 우리은행</span><span>${available(e)<e.amount?'연결 '+won(e.amount-available(e)):'연결 전'}</span></div><div class="bank-entry-actions"><span class="pill ${e.business==='mimine'?'green':e.business==='unclassified'?'amber':''}">${{mimine:'미미네',adw:'하루온종일',unclassified:'미분류',other:'기타'}[e.business]}</span><button class="text-button" data-action="classify" data-id="${e.id}">분류 변경${icon('right')}</button>${available(e)===0?'<span class="pill green">연결 완료</span>':''}</div></div>`).join('')||emptyHTML('입금내역이 없어요','예시 입금을 추가해 체험해 보세요.')}</div>`}<p class="section-note">예시 데이터로 동작합니다. 실제 은행·POS 연동 상태를 나타내는 화면이 아닙니다.</p>`;
}
function productVisual(p){let image='';try{const url=new URL(p.imageUrl);if(['https:','http:'].includes(url.protocol)&&!url.username&&!url.password)image=url.href;}catch{}return`<div class="product-visual" style="--product-color:${p.color||'#58785f'};--product-bg:${p.bg||'#e9f0e3'}">${icon(p.category==='음료'?'drink':'ramen')}${image?`<img class="product-image" src="${esc(image)}" alt="${esc(p.name)} 상품 사진" loading="lazy" decoding="async" draggable="false">`:''}</div>`;}
document.addEventListener('error',event=>{if(event.target?.matches?.('img.product-image'))event.target.remove();},true);
function renderProducts(){let ps=db.products.filter(p=>view.productFilter==='low'?stock(p)<=p.min:view.productFilter==='expiry'?expiring(p):true).filter(p=>p.name.toLowerCase().includes(view.productQuery.toLowerCase()));return`<div class="product-page">${heading('PRODUCTS & STOCK','상품·재고','입고 기록과 유통기한을 한 화면에서 관리하세요.',`<button class="secondary compact" data-action="product-new">${icon('plus')}상품 등록</button>`)}<div class="product-toolbar"><div class="product-filters">${[['all','전체',db.products.length],['low','재고 부족',db.products.filter(p=>stock(p)<=p.min).length],['expiry','유통기한 임박',db.products.filter(expiring).length]].map(([id,l,n])=>`<button class="chip ${view.productFilter===id?'active':''}" data-action="product-filter" data-value="${id}">${l}<span>${n}</span></button>`).join('')}</div><label class="search-box">${icon('search')}<input data-search="products" placeholder="상품명 검색" aria-label="상품 검색" value="${esc(view.productQuery)}"></label></div><div class="product-grid">${ps.map(p=>{const qty=stock(p),e=expiry(p),days=e?daysBetween(TODAY,e):null;return`<button class="product-card" data-action="product-detail" data-id="${p.id}">${productVisual(p)}${qty<=p.min?'<span class="pill red">재고 부족</span>':expiring(p)?`<span class="pill amber">${days<0?'기한 지남':'D−'+days}</span>`:''}<h3>${esc(p.name)}</h3><span class="category">${esc(p.category)} · 판매가 ${won(p.price)}</span><div class="product-stock"><strong class="${qty<=p.min?'negative':''}">${fmt(qty)}<span>개</span></strong><small>기준 ${p.min}개</small></div><div class="product-foot ${expiring(p)?'attention':''}">${e?'유통기한 '+e.replaceAll('-','.'):'유통기한 미등록'}</div></button>`;}).join('')||emptyHTML('조건에 맞는 상품이 없어요','다른 필터나 검색어로 확인하세요.')}</div><p class="section-note">재고는 입고·조정 기록 기준입니다. 상품을 누르면 입고, 재고 조정, 상품 수정을 할 수 있어요.</p></div>`;}
function renderReports(){const bounds=view.reportRange==='year'?[TODAY.slice(0,4)+'-01-01',TODAY]:[view.date.slice(0,7)+'-01',view.date.slice(0,7)+'-31'];const sales=db.sales.filter(s=>inRange(s,bounds)),expenses=db.expenses.filter(e=>inRange(e,bounds));const ts=sum(sales),te=sum(expenses);const cats={};expenses.forEach(e=>cats[e.category]=(cats[e.category]||0)+e.amount);const catsArr=Object.entries(cats).sort((a,b)=>b[1]-a[1]);const days=view.reportRange==='year'?daysBetween('2026-01-01',TODAY)+1:Number(view.date.slice(8));const avg=Math.round(ts/days);const monthDays=new Date(Date.UTC(2026,Number(view.date.slice(5,7)),0)).getUTCDate();const week=Array.from({length:7},(_,i)=>addDays(view.date,i-6));return heading('INSIGHTS','매출 분석','숫자는 간결하게, 필요한 흐름은 분명하게.',`<button class="secondary compact" data-action="export">${icon('download')}장부 내보내기</button>`)+`<div class="page-toolbar"><div class="segmented"><button class="${view.reportRange==='month'?'active':''}" data-action="report-range" data-value="month">이번 달</button><button class="${view.reportRange==='year'?'active':''}" data-action="report-range" data-value="year">올해</button></div><span class="pill">${bounds[0].replaceAll('-','.')}부터</span></div><div class="summary-grid"><div class="summary-card"><small>총매출</small><strong class="positive">${moneyMarkup(ts)}</strong><em>${sales.length}일 기록</em></div><div class="summary-card"><small>총지출</small><strong>${moneyMarkup(te)}</strong><em>${expenses.length}건 기록</em></div><div class="summary-card"><small>매출 − 지출</small><strong class="${changeTone(ts-te)}">${moneyMarkup(ts-te)}</strong><em>입력된 장부 기준</em></div></div><div class="report-grid"><div class="stack"><section class="card"><div class="card-header"><h2>최근 7일의 흐름</h2><span class="chart-legend"><i></i> 매출</span></div>${chart(week,'report-chart')}<div class="chart-note"><span>선택 기간 하루 평균</span><strong>${won(avg)}</strong></div></section><section class="card"><div class="card-header"><h2>날짜별 비교</h2><small>최근 7일</small></div><table class="report-table"><thead><tr><th>날짜</th><th>매출</th><th>지출</th><th>매출 − 지출</th></tr></thead><tbody>${week.slice().reverse().map(d=>{const s=saleOn(d)?.amount||0,e=sum(db.expenses.filter(e=>e.date===d));return`<tr><td>${md(d)} ${weekday(d)}</td><td>${fmt(s)}</td><td>${fmt(e)}</td><td class="${s-e<0?'negative':''}">${fmt(s-e)}</td></tr>`;}).join('')}</tbody></table><p class="section-note">단위: 원</p></section></div><div class="stack"><section class="card"><div class="card-header"><h2>어디에 지출했나요?</h2><small>항목별 비중</small></div><div class="expense-breakdown">${catsArr.map(([c,n],i)=>`<div><div class="breakdown-head"><strong>${esc(c)}</strong><span>${won(n)} · ${Math.round(n/Math.max(te,1)*100)}%</span></div><div class="breakdown-track"><div class="breakdown-bar" style="width:${n/Math.max(te,1)*100}%;background:${['#d07b64','#a8b492','#c5b58e','#a8bec0','#b9a1b2'][i%5]}"></div></div></div>`).join('')||'<p class="muted">지출 기록이 없어요.</p>'}</div></section><section class="card goal-panel"><div class="card-header"><h2>${view.reportRange==='year'?'하루 평균 매출':'이달 말 예상 매출'}</h2><span class="pill">단순 추정</span></div><div class="goal-value">${won(view.reportRange==='year'?avg:Math.round(ts/days*monthDays))}</div><p>${view.reportRange==='year'?'올해 누적 매출 ÷ 올해 경과 일수':'누적 매출 ÷ 경과 일수 × 이달 전체 일수'}<br>요일·휴점·행사에 따른 차이는 반영하지 않습니다.</p></section></div></div>`;}
function render(){document.body.classList.toggle('large-type',!!db.settings.largeType);navHTML();$('#main').innerHTML=({today:renderToday,ledger:renderLedger,bank:renderBank,products:renderProducts,reports:renderReports}[view.page]||renderToday)();document.title='미미네 · '+({today:'매출·비용 흐름',ledger:'장부',bank:'입금 확인',products:'상품·재고',reports:'비교·예측'}[view.page]);}
function navigate(page){view.page=['today','ledger','bank','products','reports'].includes(page)?page:'today';view.query='';view.productQuery='';if(location.hash!=='#'+view.page)history.replaceState(null,'','#'+view.page);render();window.scrollTo({top:0,behavior:'instant'});}
function closeModal(){const oldFocus=previousFocus;$('#modal-root').innerHTML='';modalName='';modalContext={};document.body.style.overflow='';$('.app-shell').inert=false;$('#mobile-nav').inert=false;oldFocus?.isConnected&&oldFocus.focus({preventScroll:true});}
function sheet(title,body,footer='',options={}){if(!modalName)previousFocus=document.activeElement;modalName=options.name||'sheet';$('#modal-root').innerHTML=`<div class="modal-overlay" data-overlay="true"><section class="sheet" role="dialog" aria-modal="true" aria-labelledby="sheet-title" tabindex="-1"><div class="sheet-head"><div><p class="eyebrow">MIMINE · ${options.caption||'QUICK ACTION'}</p><h2 id="sheet-title">${title}</h2></div><button class="icon-button" data-action="close-modal" aria-label="닫기">${icon('close')}</button></div>${options.form?`<form id="${options.form}" class="sheet-form">`:''}<div class="sheet-body">${body}<div class="inline-error" id="form-error" role="alert"></div></div>${footer?`<div class="sheet-footer">${footer}</div>`:''}${options.form?'</form>':''}</section></div>`;document.body.style.overflow='hidden';$('.app-shell').inert=true;$('#mobile-nav').inert=true;$('.sheet').focus({preventScroll:true});}
function showError(msg){const el=$('#form-error');if(el){el.textContent=msg;el.classList.add('show');el.scrollIntoView({block:'nearest'});}else toast(msg);}
function inputAmount(id,value=0,required=true){return`<div class="amount-field"><input id="${id}" name="${id}" data-money="true" inputmode="numeric" value="${fmt(value)}" aria-label="금액" ${required?'required':''}><span>원</span></div>`;}
function installSaleAmountReplacement(input,requestFrame=fn=>window.requestAnimationFrame?.(fn)){
 let revision=0;
 const selectExisting=()=>{
  const value=input.value,version=revision;
  input.select();
  // A tap may move the caret after focus. Restore selection after that default
  // action, without selecting again once the user has started typing.
  requestFrame(()=>{
   if(input.isConnected&&input.ownerDocument.activeElement===input&&revision===version&&input.value===value)input.select();
  });
 };
 input.addEventListener('input',()=>revision++);
 input.addEventListener('focus',selectExisting);
 input.addEventListener('click',selectExisting);
}
function field(label,html,note=''){const found=html.match(/\bid="([^"]+)"/),id=found?.[1]||uid('field');if(!found)html=html.replace(/<(input|select|textarea)\b/,`<$1 id="${id}"`);return`<div class="form-field"><label for="${id}">${label}</label>${html}${note?`<p class="field-note">${note}</p>`:''}</div>`;}
function openEntry(type='sale',id='',date=view.date){const existing=id?(type==='sale'?db.sales:db.expenses).find(r=>r.id===id):null;const initial=existing||(type==='sale'?saleOn(date):null);const r=initial||{};const entryDate=r.date||date;modalContext={entryType:type,editing:!!existing,id:r.id||'',split:false};
 const saleBody=`<div class="sale-entry-date">${field('매출일',`<input name="date" type="date" value="${entryDate}" max="${TODAY}" ${existing?'readonly':''} required aria-label="매출일">`)}</div><div class="sale-entry-primary"><label for="entry-amount">하루 총매출</label><div class="sale-entry-amount-row">${inputAmount('entry-amount',r.amount||0)}<button class="primary sale-inline-save" type="submit" aria-label="매출 저장">${icon('check')}저장</button></div></div><div class="soft-notice neutral ${initial?'':'hidden'}" id="existing-sale-note">${icon('info')}<span>기존 ${won(initial?.amount||0)} · 저장하면 해당 날짜의 일매출을 수정합니다.</span></div><div class="money-steps sale-money-steps"><button type="button" data-action="amount-add" data-target="entry-amount" data-value="10000">+1만</button><button type="button" data-action="amount-add" data-target="entry-amount" data-value="50000">+5만</button><button type="button" data-action="amount-add" data-target="entry-amount" data-value="100000">+10만</button><button type="button" data-action="amount-reset" data-target="entry-amount">지우기</button></div><details class="sale-entry-extra"><summary>결제수단·정산정보·메모 <span>선택</span>${icon('down')}</summary><button type="button" class="disclosure" data-action="toggle-split" aria-expanded="false">결제수단·정산정보 나누기${icon('down')}</button><div class="split-fields hidden" id="payment-split"><label>카드 매출<input name="card" data-money value="${fmt(r.card??r.amount??0)}" inputmode="numeric"></label><label>현금 매출<input name="cash" data-money value="${fmt(r.cash||0)}" inputmode="numeric"></label><label>기타 매출<input name="other" data-money value="${fmt(r.other||0)}" inputmode="numeric"></label><label>실제 수수료<input name="fee" data-money value="${fmt(r.fee||0)}" inputmode="numeric"></label><label>입금 예정일<input name="due" type="date" value="${r.due||''}"></label><p class="field-note">수수료는 정산표에 있는 실제 금액을 입력하세요.</p></div>${field('메모 · 선택',`<input name="note" maxlength="200" placeholder="예: 키오스크 마감 금액" value="${esc(r.note||'')}">`)}<p class="field-note">결제수단을 나누지 않으면 총매출만 저장합니다. 기존 정산정보가 있으면 현금·기타는 유지하고 카드 금액을 조정합니다. 수수료와 예정일은 실제 정산표로 확인해 주세요.</p></details>`;
 const expenseBody=`${field('지출일',`<input name="date" type="date" value="${entryDate}" max="${TODAY}" required aria-label="지출일">`)}<div class="form-field"><label for="entry-amount">지출 금액</label>${inputAmount('entry-amount',r.amount||0)}<div class="money-steps"><button type="button" data-action="amount-add" data-target="entry-amount" data-value="10000">+1만</button><button type="button" data-action="amount-add" data-target="entry-amount" data-value="50000">+5만</button><button type="button" data-action="amount-add" data-target="entry-amount" data-value="100000">+10만</button><button type="button" data-action="amount-reset" data-target="entry-amount">지우기</button></div></div><div class="form-field"><label>지출 항목</label><div class="choice-row">${['상품매입','소모품','임대료','공과금','기타'].map((c,i)=>`<label><input type="radio" name="category" value="${c}" ${(r.category||'상품매입')===c?'checked':''}><span>${c}</span></label>`).join('')}</div></div>${field('사용처 / 내용',`<input name="vendor" placeholder="예: 라면 도매 구매" value="${esc(r.vendor||'')}" maxlength="80" required aria-label="사용처 또는 내용">`)}${field('메모 · 선택',`<input name="note" placeholder="추가로 남길 내용" value="${esc(r.note||'')}" maxlength="200">`)}`;
 const body=`${!existing?`<div class="entry-type"><button type="button" data-action="entry-type" data-type="sale" class="${type==='sale'?'active':''}">매출</button><button type="button" data-action="entry-type" data-type="expense" class="${type==='expense'?'active':''}">지출</button></div>`:''}${type==='sale'?saleBody:expenseBody}`;
 sheet(type==='sale'?(entryDate===TODAY?'오늘 매출':'일매출')+(initial?' 수정':' 입력'):existing?'지출 수정':'지출 입력',body,`${existing?`<button type="button" class="danger-btn" style="flex:0 0 49px;padding:10px" data-action="delete-record" data-id="${r.id}" data-type="${type}" aria-label="기록 삭제">${icon('trash')}</button>`:''}${type==='sale'?'':`<button class="primary" type="submit">${icon('check')}${initial?'수정 저장':'저장하기'}</button>`}`,{form:'entry-form',name:'entry',caption:'QUICK ENTRY'});
 modalContext={entryType:type,editing:!!existing,id:r.id||'',split:false};
 if(type==='sale'){$('.sheet').classList.add('sale-entry-sheet');const primary=$('.sale-entry-primary');primary.after($('#form-error'));const footer=$('.sheet-footer');if(footer&&!footer.children.length)footer.remove();const amount=$('#entry-amount');amount.setAttribute('enterkeyhint','done');installSaleAmountReplacement(amount);amount.focus({preventScroll:true});amount.select();}
 if(type==='sale')$('input[name=date]',$('#entry-form')).addEventListener('change',e=>{const s=saleOn(e.target.value);$('#sheet-title').textContent=(e.target.value===TODAY?'오늘 매출':'일매출')+(s?' 수정':' 입력');if(s){modalContext.id=s.id;$('#entry-amount').value=fmt(s.amount);for(const f of ['card','cash','other','fee'])$(`[name=${f}]`,$('#entry-form')).value=fmt(s[f]||0);$('[name=due]',$('#entry-form')).value=s.due||'';$('[name=note]',$('#entry-form')).value=s.note||'';$('#existing-sale-note').classList.remove('hidden');$('#existing-sale-note span').textContent=`이 날짜에 ${won(s.amount)}이 등록돼 있어요. 저장하면 해당 일매출을 수정합니다.`;}else{modalContext.id='';$('#existing-sale-note').classList.add('hidden');$('#entry-amount').value='0';for(const f of ['card','cash','other','fee'])$(`[name=${f}]`,$('#entry-form')).value='0';$('[name=due]',$('#entry-form')).value='';$('[name=note]',$('#entry-form')).value='';}});
}
function saveEntry(form){const fd=new FormData(form),type=modalContext.entryType,date=String(fd.get('date')),amount=num(fd.get('entry-amount'));if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>TODAY)return showError('체험 기준일인 2026년 11월 3일까지 입력해 주세요.');if(type==='expense'&&amount<=0)return showError('지출 금액은 1원 이상 입력해 주세요.');if(amount>999999999)return showError('금액은 10억 원 미만으로 입력해 주세요.');if(type==='sale'){const old=saleOn(date);let card,cash,other,fee,due;if(modalContext.split){card=num(fd.get('card'));cash=num(fd.get('cash'));other=num(fd.get('other'));fee=num(fd.get('fee'));due=String(fd.get('due')||'');if(card+cash+other!==amount)return showError('카드·현금·기타의 합계를 하루 총매출과 맞춰 주세요.');if(fee>card)return showError('수수료는 카드 매출보다 클 수 없어요.');}else{cash=old?.cash||0;other=old?.other||0;if(amount<cash+other)return showError('현금·기타 합계보다 총매출이 적어요. 결제수단을 열어 금액을 확인해 주세요.');card=amount-cash-other;fee=old?.fee||0;due=old?.due||addDays(date,2);}if(fee>card)return showError('수수료가 카드 매출보다 큽니다. 정산정보를 확인해 주세요.');if(old&&linked(old)>Math.max(0,card-fee))return showError('연결된 입금보다 입금 예정액이 작습니다. 입금 화면에서 연결을 먼저 해제해 주세요.');const id=old?.id||uid('s'),record={id,date,amount,card,cash,other,fee,due,note:String(fd.get('note')||''),source:'수동 입력'};if(old)db.sales[db.sales.findIndex(s=>s.id===id)]=record;else db.sales.push(record);}else{const record={id:modalContext.id||uid('e'),date,amount,category:String(fd.get('category')||'기타'),vendor:String(fd.get('vendor')||'').trim(),note:String(fd.get('note')||'')};if(!record.vendor)return showError('사용처나 지출 내용을 입력해 주세요.');const i=db.expenses.findIndex(e=>e.id===record.id);if(i>=0)db.expenses[i]=record;else db.expenses.push(record);}view.date=date;closeModal();notifyMutation(type==='sale'?'매출을 저장했어요. 합계에 반영했습니다.':'지출을 저장했어요. 합계에 반영했습니다.');}
function deleteRecord(id,type){const list=type==='sale'?db.sales:db.expenses,record=list.find(r=>r.id===id);if(type==='sale'&&linked(record)>0)return showError('입금 연결을 먼저 해제한 뒤 매출을 삭제해 주세요.');const backup=structuredClone(db);db[type==='sale'?'sales':'expenses']=list.filter(r=>r.id!==id);closeModal();persist();render();toast('기록을 삭제했어요.',()=>{db=backup;persist();render();toast('기록을 복원했어요.');});}
function openDatePicker(){sheet('조회 날짜 선택',`${field('날짜',`<input id="chosen-date" type="date" value="${view.date}" max="${TODAY}" required>`)}<button class="secondary full" type="button" data-action="pick-today">오늘로 이동 · ${dateText(TODAY)}</button>`,`<button class="primary" type="submit">이 날짜 보기</button>`,{form:'date-form',name:'date'});}
function openRange(){sheet('조회 기간 선택',`<div class="form-grid">${field('시작일',`<input name="start" type="date" value="${view.customStart}" max="${TODAY}" required>`)}${field('종료일',`<input name="end" type="date" value="${view.customEnd}" max="${TODAY}" required>`)}</div>`,`<button class="primary" type="submit">기간 적용</button>`,{form:'range-form',name:'range'});}
function openGoal(){sheet('이번 달 매출 목표',field('목표 매출',inputAmount('goal-amount',db.goal)),'<button class="primary" type="submit">목표 저장</button>',{form:'goal-form',name:'goal'});}
function openSettings(bank=false){sheet(bank?'입금 연결 설정':'설정·연결',`${bank?`<div class="soft-notice">${icon('info')}<span>체험용 입금으로 분류·정산 연결 흐름을 확인합니다.</span></div>`:''}<div class="settings-row"><div><strong>큰 글씨</strong><small>글자를 조금 더 크게 표시합니다.</small></div><button class="switch" role="switch" aria-label="큰 글씨" aria-checked="${!!db.settings.largeType}" data-action="toggle-large"></button></div><div class="settings-row"><div><strong>자동 연결 체험</strong><small>입금자·금액·예정일이 모두 같을 때 연결합니다.</small></div><button class="switch" role="switch" aria-label="자동 연결 체험" aria-checked="${!!db.settings.autoMatch}" data-action="toggle-auto"></button></div><div class="settings-row"><div><strong>현재 연결</strong><small>우리은행·키움페이 예시 데이터</small></div><span class="pill amber">체험 모드</span></div><div class="setting-buttons"><button class="secondary" data-action="sample-bank">${icon('plus')}예시 입금 추가</button><button class="secondary" data-action="export">${icon('download')}장부 CSV 내려받기</button><button class="danger-btn" data-action="reset-confirm">${icon('refresh')}체험 데이터 초기화</button></div><div class="settings-note">이 목업에서는 매출·지출, 입금 분류·연결, 상품 등록·입고·재고 조정이 동작합니다.<br><br>입력한 내용은 ${storageAvailable?'현재 기기·브라우저에 저장됩니다. 다른 기기와 동기화되지 않습니다.':'현재 창에서만 유지됩니다.'}<br>체험 기준일: 2026년 11월 3일</div>`, '<button class="secondary" data-action="close-modal">닫기</button>',{name:'settings',caption:'PREFERENCES'});}
function openMatch(id){const s=db.sales.find(s=>s.id===id);if(!s)return;const links=db.links.filter(l=>l.saleId===id);const candidates=db.events.filter(e=>e.business==='mimine'&&available(e)>0).sort((a,b)=>Math.abs(available(a)-remaining(s))-Math.abs(available(b)-remaining(s)));modalContext={saleId:id};sheet(`${md(s.date)} 매출 · 입금 연결`,`<div class="summary-strip"><span>카드매출 − 수수료</span><strong>${won(expected(s))}</strong></div><div class="info-line"><span>연결된 입금</span><strong>${won(linked(s))}</strong></div><div class="info-line"><span>남은 금액</span><strong class="${remaining(s)?'negative':'positive'}">${won(remaining(s))}</strong></div>${links.length?`<h3 class="spacer" style="margin-bottom:10px">현재 연결</h3>${links.map(l=>{const e=db.events.find(e=>e.id===l.eventId);return`<div class="match-option"><div class="row"><strong>${esc(e?.payer||'입금')}</strong><strong>${won(l.amount)}</strong></div><p>${e?md(e.date):''} · ${l.method} 연결</p><button class="text-button accent" data-action="unlink" data-id="${l.id}">연결 해제</button></div>`;}).join('')}`:''}${remaining(s)?`<h3 class="spacer" style="margin-bottom:10px">연결할 입금 선택</h3>${candidates.map((e,i)=>`<label class="match-option"><div class="row"><span class="check-row" style="margin:0"><input type="radio" name="match-event" value="${e.id}" ${i===0?'checked':''}><strong>${esc(e.payer)}</strong></span><strong>${won(available(e))}</strong></div><p>${md(e.date)} ${e.time} · ${available(e)===remaining(s)?'금액 일치':'연결 가능 금액'}</p></label>`).join('')||'<p class="field-note">연결할 미미네 입금이 없어요. 통장내역에서 사업 구분을 확인해 주세요.</p>'}<div class="form-field spacer"><label for="match-amount">연결할 금액</label>${inputAmount('match-amount',Math.min(remaining(s),candidates[0]?available(candidates[0]):0))}<p class="field-note">일부 금액만 연결하면 나머지는 미완료로 남습니다.</p></div>`:''}`,`${remaining(s)?'<button class="primary" type="submit">선택한 입금 연결</button>':'<button class="secondary" type="button" data-action="close-modal">확인</button>'}`,{form:'match-form',name:'match',caption:'MATCH DEPOSIT'});modalContext={saleId:id};}
function saveMatch(form){const s=db.sales.find(s=>s.id===modalContext.saleId),fd=new FormData(form),e=db.events.find(e=>e.id===fd.get('match-event')),amount=num(fd.get('match-amount'));if(!e)return showError('연결할 입금을 선택해 주세요.');if(e.excluded)return showError('대상 제외한 입금입니다. 제외를 해제한 뒤 연결해 주세요.');if(!amount)return showError('연결할 금액을 입력해 주세요.');if(amount>remaining(s))return showError('매출의 남은 입금 예정액보다 크게 연결할 수 없어요.');if(amount>available(e))return showError('해당 입금의 연결 가능 금액을 넘을 수 없어요.');db.links.push({id:uid('link'),saleId:s.id,eventId:e.id,amount,method:'수동'});closeModal();notifyMutation('입금을 연결했어요. 매출 합계는 그대로 유지됩니다.');}
function autoMatch(){if(!db.settings.autoMatch)return toast('설정에서 자동 연결 체험을 먼저 켜 주세요.');const candidates=[];for(const s of db.sales){if(!remaining(s)||!s.due)continue;const matches=db.events.filter(e=>!e.excluded&&e.business==='mimine'&&isRegisteredMiminePayer(e)&&e.date===s.due&&available(e)===remaining(s));if(matches.length===1)candidates.push({s,e:matches[0]});}const unique=candidates.filter(c=>candidates.filter(x=>x.e.id===c.e.id).length===1);for(const {s,e} of unique)db.links.push({id:uid('link'),saleId:s.id,eventId:e.id,amount:remaining(s),method:'자동'});notifyMutation(unique.length?`${unique.length}건을 자동 연결했어요. 금액이 다른 입금은 직접 확인해 주세요.`:'일치하는 입금이 없어요. 금액·입금자·예정일을 확인해 주세요.');}
function openClassify(id){const e=db.events.find(e=>e.id===id);if(!e)return;sheet('입금 사업 구분',`<div class="summary-strip"><span>${esc(e.payer)}</span><strong>${won(e.amount)}</strong></div>${field('사용할 사업',`<select name="business" aria-label="입금 사업 구분">${[['mimine','미미네'],['adw','하루온종일'],['other','기타'],['unclassified','미분류']].map(([id,l])=>`<option value="${id}" ${e.business===id?'selected':''}>${l}</option>`).join('')}</select>`)}<p class="field-note">정산에 연결된 입금은 연결을 해제한 뒤 다른 사업으로 변경할 수 있어요.</p>`,'<button class="primary" type="submit">분류 저장</button>',{form:'classify-form',name:'classify'});modalContext={eventId:id};}
function openSampleBank(){const s=db.sales.find(s=>s.date==='2026-11-01');const amt=s?remaining(s):138658;sheet('예시 입금 추가',`${field('입금자',`<input name="payer" value="키움페이" maxlength="50" required>`)}${field('입금일',`<input name="date" type="date" value="${TODAY}" max="${TODAY}" required>`)}${field('입금액',inputAmount('bank-amount',amt||138658))}${field('사업 구분','<select name="business"><option value="mimine">미미네</option><option value="adw">하루온종일</option><option value="unclassified">미분류</option></select>')}<p class="field-note">새 예시 내역을 추가합니다. 실제 은행에서 조회하거나 송금하지 않습니다.</p>`,'<button class="primary" type="submit">예시 내역 추가</button>',{form:'sample-bank-form',name:'sample-bank'});}
function openProduct(id){const p=db.products.find(p=>p.id===id);if(!p)return;sheet('상품 상세',`<div class="sheet-product-hero">${productVisual(p)}<div><small>${esc(p.category)}</small><h3>${esc(p.name)}</h3><div class="product-price">${won(p.price)}</div></div></div><div class="summary-strip"><span>현재 재고</span><strong class="${stock(p)<=p.min?'negative':''}">${stock(p)}개</strong></div><div class="info-line"><span>재고 알림 기준</span><strong>${p.min}개 이하</strong></div><div class="info-line"><span>기본 매입 단가</span><strong>${won(p.cost)}</strong></div><h3 class="spacer" style="margin-bottom:10px">남은 입고분</h3>${p.batches.filter(b=>b.qty>0).map(b=>`<div class="info-line"><span>${b.expiry?'유통기한 '+b.expiry:'유통기한 미등록'}</span><strong>${b.qty}개</strong></div>`).join('')||'<p class="field-note">현재 재고가 없어요.</p>'}<div class="setting-buttons"><button class="secondary" data-action="adjust-stock" data-id="${id}">${icon('edit')}실제 재고 수량 조정</button><button class="secondary" data-action="product-edit" data-id="${id}">${icon('tag')}상품 정보 수정</button></div><p class="field-note spacer">재고는 입고·수동 조정 기준이며, 판매 시 자동 차감은 체험 범위에 포함되지 않습니다.</p>`,`<button class="primary" data-action="inbound" data-id="${id}">${icon('plus')}입고 등록</button>`,{name:'product',caption:'PRODUCT DETAIL'});}
function openProductForm(id=''){const p=db.products.find(p=>p.id===id)||{};sheet(id?'상품 정보 수정':'새 상품 등록',`${field('상품명',`<input name="name" placeholder="상품 이름" value="${esc(p.name||'')}" required maxlength="60">`)}${field('상품 종류',`<select name="category">${['라면','컵라면','음료','토핑','기타'].map(c=>`<option ${c===p.category?'selected':''}>${c}</option>`).join('')}</select>`)}<div class="form-grid">${field('판매가 (원)',`<input name="price" data-money value="${fmt(p.price||0)}" inputmode="numeric" required>`)}${field('매입 단가 (원)',`<input name="cost" data-money value="${fmt(p.cost||0)}" inputmode="numeric" required>`)}</div>${field('재고 부족 알림 (개 이하)',`<input name="min" type="number" min="0" max="100000" value="${p.min??10}" required>`)}${!id?`<div class="form-grid">${field('처음 재고 (개)',`<input name="qty" type="number" min="0" max="100000" value="0" required>`)}${field('유통기한 · 선택','<input name="expiry" type="date">')}</div>`:''}`,'<button class="primary" type="submit">상품 저장</button>',{form:'product-form',name:'product-form'});modalContext={productId:id};}
function openInbound(id){const p=db.products.find(p=>p.id===id);sheet(`${esc(p.name)} 입고`,`${field('입고일',`<input name="date" type="date" value="${TODAY}" max="${TODAY}" required>`)}<div class="form-grid">${field('입고 수량 (개)','<input name="qty" type="number" value="20" min="1" max="100000" required>')}${field('매입 단가 (원)',`<input name="cost" data-money value="${fmt(p.cost)}" inputmode="numeric" required>`)}</div>${field('유통기한 · 선택','<input name="expiry" type="date">')}<div class="summary-strip"><span>입고 금액</span><strong id="inbound-total">${won(p.cost*20)}</strong></div><label class="check-row"><input name="addExpense" type="checkbox">이 입고 금액을 지출에도 함께 등록</label><p class="field-note">이미 지출을 입력했다면 체크하지 마세요. 입고 재고만 추가합니다.</p>`,'<button class="primary" type="submit">입고 저장</button>',{form:'inbound-form',name:'inbound'});modalContext={productId:id};}
function openAdjust(id){const p=db.products.find(p=>p.id===id);sheet('실제 재고 수량 조정',`<p class="subtext" style="margin:0 0 18px">${esc(p.name)} · 기록 재고 ${stock(p)}개</p>${field('실제 남은 수량 (개)',`<input name="qty" type="number" min="0" max="100000" value="${stock(p)}" required>`)}${field('조정 사유','<select name="reason"><option>실제 수량 확인</option><option>판매 수량 반영</option><option>폐기·파손</option></select>')}<p class="field-note">수량을 줄이면 유통기한이 빠른 입고분부터 차감합니다. 늘어난 수량은 유통기한 미등록 입고분으로 추가됩니다.</p>`,'<button class="primary" type="submit">재고 수량 적용</button>',{form:'adjust-form',name:'adjust'});modalContext={productId:id};}
function exportCSV(){const bounds=['today','reports'].includes(view.page)?[flow.start,flow.end]:rangeBounds();const records=allRecords(bounds);const cell=v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return'"'+s.replaceAll('"','""')+'"';};const lines=[['날짜','구분','항목','내용','금액(원)','카드(원)','현금(원)','메모'],...records.map(r=>[r.date,r.type==='sale'?'매출':'지출',r.category||'일매출',r.vendor||'일매출 마감',r.amount,r.card??'',r.cash??'',r.note||''])];const blob=new Blob(['\ufeff'+lines.map(row=>row.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`미미네_장부_${bounds[0]}_${bounds[1]}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('선택 기간의 장부 CSV를 내려받았어요.');}
function submitForm(form){const fd=new FormData(form);switch(form.id){case'entry-form':saveEntry(form);break;case'date-form':view.date=$('#chosen-date').value;closeModal();render();break;case'range-form':{const a=String(fd.get('start')),b=String(fd.get('end'));if(a>b)return showError('시작일은 종료일보다 앞서야 합니다.');view.customStart=a;view.customEnd=b;view.range='custom';closeModal();render();break;}case'goal-form':db.goal=num(fd.get('goal-amount'));if(db.goal<=0)return showError('목표 금액을 1원 이상 입력해 주세요.');closeModal();notifyMutation('이번 달 목표를 저장했어요.');break;case'match-form':saveMatch(form);break;case'classify-form':{const e=db.events.find(e=>e.id===modalContext.eventId),business=String(fd.get('business'));if(business!=='mimine'&&db.links.some(l=>l.eventId===e.id))return showError('정산 연결을 먼저 해제해 주세요.');e.business=business;closeModal();notifyMutation('입금 사업 구분을 저장했어요.');break;}case'sample-bank-form':{const amount=num(fd.get('bank-amount'));if(amount<=0)return showError('입금액을 입력해 주세요.');db.events.push({id:uid('bank'),date:String(fd.get('date')),time:'12:00',payer:String(fd.get('payer')).trim(),amount,business:String(fd.get('business')),note:'사용자가 추가한 예시 입금'});closeModal();notifyMutation('예시 입금을 추가했어요. 입금 화면에서 연결할 수 있습니다.');break;}case'product-form':{const name=String(fd.get('name')||'').trim();if(!name)return showError('상품명을 입력해 주세요.');const duplicate=db.products.some(p=>p.name===name&&p.id!==modalContext.productId);if(duplicate)return showError('같은 이름의 상품이 있어요. 기존 상품을 확인해 주세요.');const p=db.products.find(p=>p.id===modalContext.productId);const values={name,category:String(fd.get('category')),price:num(fd.get('price')),cost:num(fd.get('cost')),min:num(fd.get('min'))};if(p)Object.assign(p,values);else db.products.push({...values,id:uid('p'),color:'#6d8564',bg:'#eaf0e3',batches:num(fd.get('qty'))?[{id:uid('b'),qty:num(fd.get('qty')),expiry:String(fd.get('expiry')||''),date:TODAY}]:[]});closeModal();notifyMutation('상품 정보를 저장했어요.');break;}case'inbound-form':{const p=db.products.find(p=>p.id===modalContext.productId),qty=num(fd.get('qty')),cost=num(fd.get('cost')),date=String(fd.get('date'));if(qty<1)return showError('입고 수량을 1개 이상 입력해 주세요.');p.batches.push({id:uid('b'),qty,cost,expiry:String(fd.get('expiry')||''),date});if(fd.get('addExpense')==='on')db.expenses.push({id:uid('e'),date,amount:qty*cost,category:'상품매입',vendor:p.name+' 입고 '+qty+'개',note:'입고와 함께 등록'});closeModal();notifyMutation(`${p.name} ${qty}개를 입고했어요.${fd.get('addExpense')==='on'?' 지출에도 반영했습니다.':''}`);break;}case'adjust-form':{const p=db.products.find(p=>p.id===modalContext.productId),target=num(fd.get('qty')),current=stock(p);if(target<current){let diff=current-target;for(const b of [...p.batches].sort((a,b)=>(a.expiry||'9999').localeCompare(b.expiry||'9999'))){const n=Math.min(diff,b.qty);b.qty-=n;diff-=n;if(!diff)break;}}else if(target>current)p.batches.push({id:uid('b'),qty:target-current,date:TODAY,expiry:''});p.lastAdjustment={date:TODAY,reason:String(fd.get('reason')),from:current,to:target};closeModal();notifyMutation('실제 수량으로 재고를 조정했어요.');break;}}}
function action(el){const a=el.dataset.action,id=el.dataset.id,value=el.dataset.value;switch(a){case'navigate':closeIfNeeded();navigate(el.dataset.page);break;case'today-sale':openEntry('sale','',TODAY);break;case'entry':openEntry(el.dataset.type||'sale');break;case'entry-type':{const date=$('#entry-form [name=date]')?.value||view.date;openEntry(el.dataset.type,'',date);break;}case'edit-record':openEntry(el.dataset.type,id);break;case'close-modal':closeModal();break;case'undo':{const fn=undoFn;undoFn=null;fn?.();break;}case'date-prev':view.date=addDays(view.date,-1);render();break;case'date-next':if(view.date<TODAY){view.date=addDays(view.date,1);render();}break;case'date-picker':openDatePicker();break;case'pick-today':view.date=TODAY;closeModal();render();break;case'chart-date':view.date=el.dataset.date;navigate('today');break;case'go-ledger-today':view.range='today';navigate('ledger');break;case'go-pending':view.bankFilter='pending';view.bankTab='compare';navigate('bank');break;case'go-products':view.productFilter=el.dataset.filter;navigate('products');break;case'ledger-type':view.ledgerType=value;render();break;case'range':if(el.dataset.range==='custom')openRange();else{view.range=el.dataset.range;render();}break;case'amount-add':{const input=$('#'+el.dataset.target);input.value=fmt(num(input.value)+Number(value));break;}case'amount-reset':$('#'+el.dataset.target).value='0';$('#'+el.dataset.target).focus();break;case'toggle-split':modalContext.split=!modalContext.split;$('#payment-split').classList.toggle('hidden',!modalContext.split);el.setAttribute('aria-expanded',String(modalContext.split));break;case'delete-record':deleteRecord(id,el.dataset.type);break;case'bank-tab':view.bankTab=value;render();break;case'bank-filter':view.bankFilter=value;render();break;case'business-filter':view.bankBusiness=value;render();break;case'auto-match':autoMatch();break;case'match':openMatch(id);break;case'unlink':{const saleId=modalContext.saleId;db.links=db.links.filter(l=>l.id!==id);persist();render();openMatch(saleId);toast('입금 연결을 해제했어요.');break;}case'classify':openClassify(id);break;case'sample-bank':openSampleBank();break;case'bank-settings':openSettings(true);break;case'product-filter':view.productFilter=value;render();break;case'product-detail':openProduct(id);break;case'product-new':openProductForm();break;case'product-edit':openProductForm(id);break;case'inbound':openInbound(id);break;case'adjust-stock':openAdjust(id);break;case'goal':openGoal();break;case'settings':openSettings();break;case'toggle-large':db.settings.largeType=!db.settings.largeType;persist();render();el.setAttribute('aria-checked',String(db.settings.largeType));break;case'toggle-auto':db.settings.autoMatch=!db.settings.autoMatch;persist();el.setAttribute('aria-checked',String(db.settings.autoMatch));break;case'reset-confirm':sheet('체험 데이터를 처음으로 되돌릴까요?','<div class="confirmation"><p>이 브라우저에서 추가·수정한 체험 기록이 지워지고 처음의 예시 데이터로 돌아갑니다.</p></div>','<button class="secondary" data-action="settings">취소</button><button class="primary" data-action="reset-data">초기화</button>',{name:'confirm'});break;case'reset-data':db=seed();closeModal();view.date=TODAY;notifyMutation('처음의 예시 데이터로 돌아왔어요.');break;case'export':exportCSV();break;case'report-range':view.reportRange=value;render();break;}}
function closeIfNeeded(){if(modalName)closeModal();}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el){if(el.tagName==='BUTTON'&&!el.hasAttribute('type')){const form=el.closest('form');if(form)e.preventDefault();}action(el);}else if(e.target.matches('[data-overlay=true]'))closeModal();});
document.addEventListener('submit',e=>{e.preventDefault();try{Promise.resolve(submitForm(e.target)).catch(err=>{showError('저장하지 못했어요. '+(err.message||'입력 내용을 확인해 주세요.'));console.error(err);});}catch(err){showError('저장하지 못했어요. 입력 내용을 확인하고 다시 시도해 주세요.');console.error(err);}});
document.addEventListener('input',e=>{const input=e.target;if(input.matches('[data-money]')){const start=input.selectionStart,old=input.value;input.value=old===''?'':fmt(num(old));if(start===old.length)input.setSelectionRange?.(input.value.length,input.value.length);}if(input.dataset.search){const kind=input.dataset.search,pos=input.selectionStart;if(kind==='ledger')view.query=input.value;else view.productQuery=input.value;render();const next=$(`[data-search=${kind}]`);next.focus();next.setSelectionRange(pos,pos);}if(input.closest('#inbound-form')){const f=input.closest('form');$('#inbound-total').textContent=won(num($('[name=qty]',f).value)*num($('[name=cost]',f).value));}});
document.addEventListener('change',e=>{if(e.target.name==='match-event'){const event=db.events.find(x=>x.id===e.target.value),s=db.sales.find(x=>x.id===modalContext.saleId);if(event&&s)$('#match-amount').value=fmt(Math.min(remaining(s),available(event)));}});
document.addEventListener('keydown',e=>{if(!modalName)return;if(e.key==='Escape'){e.preventDefault();closeModal();return;}if(e.key==='Tab'){const items=$$('.sheet button,.sheet input,.sheet select,.sheet textarea,.sheet a').filter(x=>!x.disabled&&x.getClientRects().length),first=items[0],last=items.at(-1);if(!items.length){e.preventDefault();return;}if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('.sheet'))){e.preventDefault();last.focus();}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===$('.sheet'))){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(['today','ledger','bank','products','reports'].includes(page))navigate(page);});
const firstPage=location.hash.slice(1);if(['today','ledger','bank','products','reports'].includes(firstPage))view.page=firstPage;
render();
